#!/usr/bin/env python3
"""
FertiTerra: replicate Hertility's page structure (batch 1).

  1. components/ft/sections.tsx        - test-page sections (Hertility's shape)
  2. app/test-kits/page.tsx            - rebuilt to their test hub
  3. app/test-kits/hormone-fertility   - sections appended BELOW your screening flow
  4. components/ft/symptom-sections.tsx- symptoms sections
  5. app/symptoms/page.tsx             - their symptoms page order, your 12 cards kept

Nothing you already have is deleted. Backups: <file>.bak-before-sections
Run from the Fertiterra repo root:   python3 apply_pages.py
"""
import os, sys, shutil, base64

MARK = "ft-sections-v2"
SECTIONS = os.path.join("components", "ft", "sections.tsx")
SYMPTOMS = os.path.join("components", "ft", "symptom-sections.tsx")
HUB = os.path.join("app", "test-kits", "page.tsx")
TEST = os.path.join("app", "test-kits", "hormone-fertility", "page.tsx")
SYMPG = os.path.join("app", "symptoms", "page.tsx")

SECTIONS_SRC = base64.b64decode("").decode()
SYMPTOMS_SRC = base64.b64decode("").decode()
HUB_SRC = base64.b64decode("").decode()

for p in (HUB, TEST, SYMPG):
    if not os.path.exists(p):
        sys.exit("Missing " + p + ". Run this from the Fertiterra repo root.")

hub = open(HUB, encoding="utf-8").read()
test = open(TEST, encoding="utf-8").read()
symp = open(SYMPG, encoding="utf-8").read()

if MARK in hub or MARK in symp:
    sys.exit("Already applied. Nothing to do.")

# ---- anchors first: prove every placement before writing anything ----------
if "</main>" not in test or "</main>" not in symp:
    sys.exit("Could not find </main>. Stopped, nothing written.")
anchor_sym = '<section className="mt-16">'
if anchor_sym not in symp:
    sys.exit("Could not find the first symptoms section. Stopped, nothing written.")

os.makedirs(os.path.dirname(SECTIONS), exist_ok=True)
open(SECTIONS, "w", encoding="utf-8").write(SECTIONS_SRC)
open(SYMPTOMS, "w", encoding="utf-8").write(SYMPTOMS_SRC)

def add_import(src, line):
    lines = src.split("\n")
    last = max(i for i, l in enumerate(lines) if l.startswith("import "))
    lines.insert(last + 1, line)
    return "\n".join(lines)

# ---- 2. hub ---------------------------------------------------------------
shutil.copy(HUB, HUB + ".bak-before-sections")
open(HUB, "w", encoding="utf-8").write(HUB_SRC)

# ---- 3. test page: append below the existing flow --------------------------
shutil.copy(TEST, TEST + ".bak-before-sections")
test = add_import(test, 'import { TestTierCards, StageCards, SupportTabs, HormonePanel, ConsultationBand, ComparisonTable, PartnerBand, FaqAccordion } from "@/components/ft/sections"')
block = """
        {/* """ + MARK + """: Hertility-shaped sections, FertiTerra branding */}
        <TestTierCards />
        <StageCards />
        <HormonePanel />
        <ConsultationBand />
        <SupportTabs />
        <ComparisonTable />
        <PartnerBand />
        <FaqAccordion />
"""
i = test.index("</main>")
test = test[:i] + block + "      " + test[i:]
for a, b in [("rose-500", "[#1F3D33]"), ("rose-600", "[#1F3D33]"), ("rose-400", "[#1F3D33]"),
             ("rose-50", "[#E4EDE6]"), ("rose-100", "[#E4EDE6]")]:
    test = test.replace(a, b)
open(TEST, "w", encoding="utf-8").write(test)

# ---- 5. symptoms page -----------------------------------------------------
shutil.copy(SYMPG, SYMPG + ".bak-before-sections")
symp = add_import(symp, 'import { SymptomByline, SymptomsIntro, WhatIsImbalance, ImbalanceVsCondition, OtherSymptoms, WhatToDoNext, ManagingSymptoms, HowWeCanHelp } from "@/components/ft/symptom-sections"')

# intro band goes directly above your first card section
j = symp.index(anchor_sym)
symp = symp[:j] + """{/* """ + MARK + """: intro band */}
        <SymptomByline />
        <SymptomsIntro />

        """ + symp[j:]

tail = """
        {/* """ + MARK + """: explainer sections */}
        <WhatIsImbalance />
        <ImbalanceVsCondition />
        <OtherSymptoms />
        <WhatToDoNext />
        <ManagingSymptoms />
        <HowWeCanHelp />
"""
k = symp.index("</main>")
symp = symp[:k] + tail + "      " + symp[k:]
open(SYMPG, "w", encoding="utf-8").write(symp)

print("Done.")
print("  added   : " + SECTIONS)
print("  added   : " + SYMPTOMS)
print("  rewrote : " + HUB)
print("  appended: " + TEST)
print("  appended: " + SYMPG)
print("")
print("Prices in sections.tsx: 485,000 RWF (Advanced) and 385,000 RWF (Standard),")
print("converted from Hertility's 249 and 199 GBP at 1 GBP = 1,941.30 RWF.")
